double fa = f(a);
double fb = f(b);
if (fa == 0.0) return a;
if (fb == 0.0) return b;
if (fa * fb > 0.0) return std::numeric_limits<double>::quiet_NaN();

double left = a;
double right = b;
double mid = left;

for (unsigned int iter = 0; iter < max_iter; ++iter) {
    mid = (left + right) * 0.5;
    double fm = f(mid);
    if (std::fabs(fm) <= precision || (right - left) * 0.5 <= precision) {
        return mid;
    }
    if (fa * fm < 0.0) {
        right = mid;
        fb = fm;
    } else {
        left = mid;
        fa = fm;
    }
}
return mid;

